    assertOutput("${1000.15}; " + "${1000.15?string(',##.#;;groupingSeparator=\" \"')}; " + "<#setting locale='de_DE'>${1000.15}; " + "<#setting numberFormat='0.0;;roundingMode=down'>${1000.15}", "1_000.2; 10 00.2; 1_000,2; 1000,1");
    assertErrorContains("${1?string('#E')}", TemplateException.class, "\"#E\"", "format string", "exponential");
    assertErrorContains("<#setting numberFormat='#E'>${1}", TemplateException.class, "\"#E\"", "format string", "exponential");
    assertErrorContains("<#setting numberFormat=';;foo=bar'>${1}", TemplateException.class, "\"foo\"", "supported");
    assertErrorContains("<#setting numberFormat='0;;roundingMode=unnecessary'>${1.5}", TemplateException.class, "can't format", "1.5", "UNNECESSARY");
