@Test
public void newInstanceTest() throws Exception {
    {
        TestBean1 res = (TestBean1) _ObjectBuilderSettingEvaluator.eval("freemarker.core.ObjectBuilderSettingsTest$TestBean1", Object.class, false, _SettingEvaluationEnvironment.getCurrent());
        assertEquals(4f, res.f, 0);
        assertFalse(res.b);
    }
    {
        TestBean1 res = (TestBean1) _ObjectBuilderSettingEvaluator.eval("freemarker.core.ObjectBuilderSettingsTest$TestBean1()", Object.class, false, _SettingEvaluationEnvironment.getCurrent());
        assertEquals(4f, res.f, 0);
        assertFalse(res.b);
    }
    {
        TestBean1 res = (TestBean1) _ObjectBuilderSettingEvaluator.eval("freemarker.core.ObjectBuilderSettingsTest$TestBean1(1.5, -20, 8589934592, true)", Object.class, false, _SettingEvaluationEnvironment.getCurrent());
        assertEquals(1.5f, res.f, 0);
        assertEquals(Integer.valueOf(-20), res.i);
        assertEquals(8589934592l, res.l);
        assertTrue(res.b);
    }
    {
        TestBean1 res = (TestBean1) _ObjectBuilderSettingEvaluator.eval("freemarker.core.ObjectBuilderSettingsTest$TestBean1(1, true)", Object.class, false, _SettingEvaluationEnvironment.getCurrent());
        assertEquals(2f, res.f, 0);
        assertEquals(Integer.valueOf(1), res.i);
        assertEquals(2l, res.l);
        assertTrue(res.b);
    }
    {
        TestBean1 res = (TestBean1) _ObjectBuilderSettingEvaluator.eval("freemarker.core.ObjectBuilderSettingsTest$TestBean1(11, 22)", Object.class, false, _SettingEvaluationEnvironment.getCurrent());
        assertEquals(3f, res.f, 0);
        assertEquals(Integer.valueOf(11), res.i);
        assertEquals(22l, res.l);
        assertFalse(res.b);
    }
    {
        TestBean1 res = (TestBean1) _ObjectBuilderSettingEvaluator.eval("freemarker.core.ObjectBuilderSettingsTest$TestBean1(p1 = 1, p2 = 2, p3 = true, p4 = 's')", Object.class, false, _SettingEvaluationEnvironment.getCurrent());
        assertEquals(4f, res.f, 0);
        assertFalse(res.b);
        assertEquals(1d, res.getP1(), 0);
        assertEquals(2, res.getP2());
        assertTrue(res.isP3());
        assertEquals("s", res.getP4());
    }
    {
        TestBean1 res = (TestBean1) _ObjectBuilderSettingEvaluator.eval("freemarker.core.ObjectBuilderSettingsTest$TestBean1(" + "null, 2, p1 = 1, p2 = 2, p3 = false, p4 = null)", Object.class, false, _SettingEvaluationEnvironment.getCurrent());
        assertNull(res.i);
        assertEquals(2, res.l, 0);
        assertEquals(3f, res.f, 0);
        assertFalse(res.b);
        assertEquals(1d, res.getP1(), 0);
        assertEquals(2, res.getP2());
        assertFalse(res.isP3());
        assertNull(res.getP4());
    }
    {
        // Deliberately odd spacings
        TestBean1 res = (TestBean1) _ObjectBuilderSettingEvaluator.eval("\t\tfreemarker . core.\n\tObjectBuilderSettingsTest$TestBean1(\n\r\tp1=1\n,p2=2,p3=true,p4='s'  )", Object.class, false, _SettingEvaluationEnvironment.getCurrent());
        assertEquals(4f, res.f, 0);
        assertFalse(res.b);
        assertEquals(1d, res.getP1(), 0);
        assertEquals(2, res.getP2());
        assertTrue(res.isP3());
        assertEquals("s", res.getP4());
    }
    {
        TestBean1 res = (TestBean1) _ObjectBuilderSettingEvaluator.eval("freemarker.core.ObjectBuilderSettingsTest$TestBean1(1, true, p2 = 2)", Object.class, false, _SettingEvaluationEnvironment.getCurrent());
        assertEquals(2f, res.f, 0);
        assertEquals(Integer.valueOf(1), res.i);
        assertEquals(2l, res.l);
        assertTrue(res.b);
        assertEquals(0d, res.getP1(), 0);
        assertEquals(2, res.getP2());
        assertFalse(res.isP3());
    }
}

