    final Configuration cfg = new Configuration();
    {
        Properties props = new Properties();
        props.setProperty(Configurable.OBJECT_WRAPPER_KEY, "freemarker.ext.beans.BeansWrapper(2.3.21)");
        props.setProperty(Configurable.ARITHMETIC_ENGINE_KEY, "freemarker.core.ObjectBuilderSettingsTest$DummyArithmeticEngine");
        props.setProperty(Configurable.TEMPLATE_EXCEPTION_HANDLER_KEY, "freemarker.core.ObjectBuilderSettingsTest$DummyTemplateExceptionHandler");
        props.setProperty(Configuration.CACHE_STORAGE_KEY, "freemarker.core.ObjectBuilderSettingsTest$DummyCacheStorage()");
        props.setProperty(Configurable.NEW_BUILTIN_CLASS_RESOLVER_KEY, "freemarker.core.ObjectBuilderSettingsTest$DummyNewBuiltinClassResolver()");
