    assertEqualsEvaled(Integer.valueOf(1), "1");
    assertEqualsEvaled(Double.valueOf(1), "1.0");
    assertEqualsEvaled(Long.valueOf(2147483649l), "2147483649");
    assertEqualsEvaled(Double.valueOf(1), "1d");
    assertEqualsEvaled(Double.valueOf(1), "1D");
    assertEqualsEvaled(Float.valueOf(1), "1f");
    assertEqualsEvaled(Float.valueOf(1), "1F");
    assertEqualsEvaled(Long.valueOf(1), "1l");
    assertEqualsEvaled(Long.valueOf(1), "1L");
    assertEqualsEvaled(BigDecimal.valueOf(1), "1bd");
    assertEqualsEvaled(BigDecimal.valueOf(1), "1Bd");
    assertEqualsEvaled(BigDecimal.valueOf(1), "1BD");
    assertEqualsEvaled(BigInteger.valueOf(1), "1bi");
    assertEqualsEvaled(BigInteger.valueOf(1), "1bI");
    assertEqualsEvaled(Float.valueOf(1.5f), "1.5f");
    assertEqualsEvaled(Double.valueOf(1.5), "1.5d");
    assertEqualsEvaled(BigDecimal.valueOf(1.5), "1.5bd");
    assertEqualsEvaled(ImmutableList.of(-1, -0.5, new BigDecimal("-0.1")), "[ -1, -0.5, -0.1bd ]");
    assertEqualsEvaled(ImmutableMap.of(-1, -11, -0.5, -0.55, new BigDecimal("-0.1"), new BigDecimal("-0.11")), "{ -1: -11, -0.5: -0.55, -0.1bd: -0.11bd }");
}

@Test
public void testStaticFields() throws Exception {
    {
        TestBean1 res = (TestBean1) _ObjectBuilderSettingEvaluator.eval("freemarker.core.ObjectBuilderSettingsTest$TestBean1(" + "freemarker.core.ObjectBuilderSettingsTest$TestStaticFields.CONST, true)", Object.class, false, _SettingEvaluationEnvironment.getCurrent());
        assertEquals(TestStaticFields.CONST, (int) res.i);
    }
    {
        TestBean1 res = (TestBean1) _ObjectBuilderSettingEvaluator.eval("freemarker.core.ObjectBuilderSettingsTest$TestBean1(" + "p2 = freemarker.core.ObjectBuilderSettingsTest$TestStaticFields.CONST)", Object.class, false, _SettingEvaluationEnvironment.getCurrent());
        assertEquals(TestStaticFields.CONST, res.getP2());
    }
    assertEqualsEvaled(123, "freemarker.core.ObjectBuilderSettingsTest$TestStaticFields.CONST");
    // With shorthand class name:
    assertEqualsEvaled(Configuration.AUTO_DETECT_TAG_SYNTAX, "Configuration.AUTO_DETECT_TAG_SYNTAX");
    try {
        _ObjectBuilderSettingEvaluator.eval("freemarker.core.ObjectBuilderSettingsTest$TestBean1(" + "p2 = freemarker.core.ObjectBuilderSettingsTest$TestStaticFields.CONST())", Object.class, false, _SettingEvaluationEnvironment.getCurrent());
        fail();
    } catch (_ObjectBuilderSettingEvaluationException e) {
        assertThat(e.getMessage(), containsString("freemarker.core.ObjectBuilderSettingsTest$TestStaticFields.CONST"));
    }
    try {
        assertEqualsEvaled(123, "freemarker.core.ObjectBuilderSettingsTest$TestStaticFields.CONST()");
        fail();
    } catch (_ObjectBuilderSettingEvaluationException e) {
        assertThat(e.getMessage(), containsString("freemarker.core.ObjectBuilderSettingsTest$TestStaticFields.CONST"));
    }
    try {
        assertEqualsEvaled(123, "java.lang.String(freemarker.core.ObjectBuilderSettingsTest$TestBean5.INSTANCE)");
        fail();
