@Test
public void testConcatWithMOs() throws IOException, TemplateException {
    assertOutput("${'\\'' + htmlMarkup} ${htmlMarkup + '\\''} ${htmlMarkup + htmlMarkup}", "&#39;<p>c <p>c&#39; <p>c<p>c");
    assertOutput("${'\\'' + htmlPlain} ${htmlPlain + '\\''} ${htmlPlain + htmlPlain}", "&#39;a &lt; {h&#39;} a &lt; {h&#39;}&#39; a &lt; {h&#39;}a &lt; {h&#39;}");
    assertErrorContains("<#ftl outputFormat='XML'>${'\\'' + htmlMarkup}", "HTML", "XML", "conversion");
    assertErrorContains("${xmlMarkup + htmlMarkup}", "HTML", "XML", "Conversion", "common");
    assertOutput("${xmlMarkup + htmlPlain}", "<p>c</p>a &lt; {h&apos;}");
    assertOutput("${xmlPlain + htmlMarkup}", "a &lt; {x&#39;}<p>c");
    assertOutput("${xmlPlain + htmlPlain}", "a &lt; {x&apos;}a &lt; {h&apos;}");
    assertOutput("${xmlPlain + htmlPlain + '\\''}", "a &lt; {x&apos;}a &lt; {h&apos;}&apos;");
    assertOutput("${htmlPlain + xmlPlain + '\\''}", "a &lt; {h&#39;}a &lt; {x&#39;}&#39;");
    assertOutput("${xmlPlain + htmlPlain + '\\''}", "a &lt; {x&apos;}a &lt; {h&apos;}&apos;");
    assertOutput("<#ftl outputFormat='XML'>${htmlPlain + xmlPlain + '\\''}", "a &lt; {h&apos;}a &lt; {x&apos;}&apos;");
    assertOutput("<#ftl outputFormat='RTF'>${htmlPlain + xmlPlain + '\\''}", "a < \\{h'\\}a < \\{x'\\}'");
    assertOutput("<#ftl outputFormat='XML'>${'\\'' + htmlPlain}", "&apos;a &lt; {h&apos;}");
    assertOutput("<#ftl outputFormat='HTML'>${'\\'' + htmlPlain}", "&#39;a &lt; {h&#39;}");
    assertOutput("<#ftl outputFormat='HTML'>${'\\'' + xmlPlain}", "&#39;a &lt; {x&#39;}");
    assertOutput("<#ftl outputFormat='RTF'>${'\\'' + xmlPlain}", "'a < \\{x'\\}");
    assertOutput("<#assign x = '\\''><#assign x += xmlMarkup>${x}", "&apos;<p>c</p>");
    assertOutput("<#assign x = xmlMarkup><#assign x += '\\''>${x}", "<p>c</p>&apos;");
    assertOutput("<#assign x = xmlMarkup><#assign x += htmlPlain>${x}", "<p>c</p>a &lt; {h&apos;}");
    assertErrorContains("<#assign x = xmlMarkup><#assign x += htmlMarkup>${x}", "HTML", "XML", "Conversion", "common");
}

