    assertOutput("<#ftl output_format='XML'>" + "${.output_format}${'\\''} " + "<#outputformat 'HTML'>${.output_format}${'\\''}</#outputformat> " + "${.output_format}${'\\''}", "XML&apos; HTML&#39; XML&apos;");
