    assertOutput("<#outputFormat 'dummy'>${.outputFormat}</#outputFormat>", "dummy");
    // Parse-time param expression:
    assertOutput("<#outputFormat 'plain' + 'Text'>${.outputFormat}</#outputFormat>", "plainText");
    assertErrorContains("<#outputFormat 'plain' + someVar + 'Text'></#outputFormat>", "someVar", "parse-time");
    assertErrorContains("<#outputFormat 'plainText'?upperCase></#outputFormat>", "?upperCase", "parse-time");
    assertErrorContains("<#outputFormat true></#outputFormat>", "string", "boolean");
    // Naming convention:
    assertErrorContains("<#outputFormat 'HTML'></#outputformat>", "convention", "#outputFormat", "#outputformat");
    assertErrorContains("<#outputformat 'HTML'></#outputFormat>", "convention", "#outputFormat", "#outputformat");
    // Empty block:
    assertOutput("${.output_format} " + "<#outputformat 'HTML'></#outputformat>" + "${.output_format}", "undefined undefined");
    // WS stripping:
    assertOutput("${.output_format}\n" + "<#outputformat 'HTML'>\n" + "  x\n" + "</#outputformat>\n" + "${.output_format}", "undefined\n  x\nundefined");
}

