@Test
public void testAutoEscPolicy() throws Exception {
    Configuration cfg = getConfiguration();
    cfg.setRegisteredCustomOutputFormats(ImmutableList.of(SeldomEscapedOutputFormat.INSTANCE, DummyOutputFormat.INSTANCE));
    assertEquals(Configuration.ENABLE_IF_DEFAULT_AUTO_ESCAPING_POLICY, cfg.getAutoEscapingPolicy());
    String commonFTL = "${'.'} ${.autoEsc?c}";
    String notEsced = ". false";
    String esced = "\\. true";
    for (int autoEscPolicy : new int[] { Configuration.ENABLE_IF_DEFAULT_AUTO_ESCAPING_POLICY, Configuration.ENABLE_IF_SUPPORTED_AUTO_ESCAPING_POLICY, Configuration.DISABLE_AUTO_ESCAPING_POLICY }) {
        cfg.setAutoEscapingPolicy(autoEscPolicy);
        String sExpted = autoEscPolicy == Configuration.ENABLE_IF_SUPPORTED_AUTO_ESCAPING_POLICY ? esced : notEsced;
        cfg.setOutputFormat(SeldomEscapedOutputFormat.INSTANCE);
        assertOutput(commonFTL, sExpted);
        cfg.setOutputFormat(UndefinedOutputFormat.INSTANCE);
        assertOutput("<#ftl outputFormat='seldomEscaped'>" + commonFTL, sExpted);
        assertOutput("<#outputFormat 'seldomEscaped'>" + commonFTL + "</#outputFormat>", sExpted);
        String dExpted = autoEscPolicy == Configuration.DISABLE_AUTO_ESCAPING_POLICY ? notEsced : esced;
        cfg.setOutputFormat(DummyOutputFormat.INSTANCE);
        assertOutput(commonFTL, dExpted);
        cfg.setOutputFormat(UndefinedOutputFormat.INSTANCE);
        assertOutput("<#ftl outputFormat='dummy'>" + commonFTL, dExpted);
        assertOutput("<#outputFormat 'dummy'>" + commonFTL + "</#outputFormat>", dExpted);
        cfg.setOutputFormat(DummyOutputFormat.INSTANCE);
        assertOutput(commonFTL + "<#outputFormat 'seldomEscaped'>" + commonFTL + "<#outputFormat 'dummy'>" + commonFTL + "</#outputFormat>" + commonFTL + "<#outputFormat 'plainText'>" + commonFTL + "</#outputFormat>" + commonFTL + "<#noAutoEsc>" + commonFTL + "</#noAutoEsc>" + commonFTL + "<#autoEsc>" + commonFTL + "</#autoEsc>" + commonFTL + "</#outputFormat>" + commonFTL + "<#noAutoEsc>" + commonFTL + "</#noAutoEsc>" + commonFTL + "<#autoEsc>" + commonFTL + "</#autoEsc>" + commonFTL, dExpted + sExpted + dExpted + sExpted + notEsced + sExpted + notEsced + sExpted + esced + sExpted + dExpted + notEsced + dExpted + esced + dExpted);
    }
}

@Test
public void testDynamicParsingBIsInherticContextOutputFormat() throws Exception {
    // Dynamic parser BI-s are supposed to use the parserConfiguration of the calling template, and ignore anything
    // inside the calling template itself. Except, the outputFormat has to come from the calling lexical context.
    String commonFTL = "Eval: ${'.outputFormat'?eval}; " + "Interpret: <#assign ipd = r\"${.outputFormat} ${'{&}'}\"?interpret><@ipd/>";
    addTemplate("t.ftlh", commonFTL);
    addTemplate("t2.ftlh", "<#outputFormat 'RTF'>" + commonFTL + "</#outputFormat>");
    assertOutputForNamed("t.ftlh", "Eval: HTML; Interpret: HTML {&amp;}");
    assertOutputForNamed("t2.ftlh", "Eval: RTF; Interpret: RTF \\{&\\}");
    assertOutput(commonFTL, "Eval: undefined; Interpret: undefined {&}");
    assertOutput("<#ftl outputFormat='RTF'>" + commonFTL + "\n" + "<#outputFormat 'XML'>" + commonFTL + "</#outputFormat>", "Eval: RTF; Interpret: RTF \\{&\\}\n" + "Eval: XML; Interpret: XML {&amp;}");
    // parser.autoEscapingPolicy is inherited too:
    assertOutput("<#ftl autoEsc=false outputFormat='XML'>" + commonFTL + " ${'.autoEsc'?eval?c}", "Eval: XML; Interpret: XML {&} false");
    assertOutput("<#ftl outputFormat='XML'>" + "<#noAutoEsc>" + commonFTL + " ${'.autoEsc'?eval?c}</#noAutoEsc>", "Eval: XML; Interpret: XML {&} false");
    assertOutput("<#ftl autoEsc=false outputFormat='XML'>" + "<#noAutoEsc>" + commonFTL + " ${'.autoEsc'?eval?c}</#noAutoEsc>", "Eval: XML; Interpret: XML {&} false");
    assertOutput("<#ftl autoEsc=false outputFormat='XML'>" + "<#autoEsc>" + commonFTL + " ${'.autoEsc'?eval?c}</#autoEsc>", "Eval: XML; Interpret: XML {&amp;} true");
    assertOutput("${.outputFormat}<#assign ftl='<#ftl outputFormat=\\'RTF\\'>$\\{.outputFormat}'> <@ftl?interpret/>", "undefined RTF");
    assertOutput("${.outputFormat}<#outputFormat 'RTF'>" + "<#assign ftl='$\\{.outputFormat}'> <@ftl?interpret/> ${'.outputFormat'?eval}" + "</#outputFormat>", "undefined RTF RTF");
}

