@Test
public void testResponseOutputCharsetInitParam() throws Exception {
    for (String initParamValue : new String[] { null, FreemarkerServlet.INIT_PARAM_VALUE_LEGACY }) {
        // Legacy mode is not aware of the outputEncoding, thus it doesn't set it:
        assertOutputEncodingEquals(// <- expected response.characterEncoding
        CFG_DEFAULT_ENCODING, // <- expected env.outputEncoding
        null, // <- init-param
        initParamValue, FOO_FTL);
        assertOutputEncodingEquals(// <- expected response.characterEncoding
        CFG_DEFAULT_ENCODING, // <- expected env.outputEncoding
        null, // <- init-param
        initParamValue, FOO_FTL);
        // Legacy mode follows the source encoding of the template:
        assertOutputEncodingEquals(// <- expected response.characterEncoding
        "UTF-8", // <- expected env.outputEncoding
        null, // <- init-param
        initParamValue, FOO_SRC_UTF8_FTL);
        // Legacy mode doesn't deal with outputEncoding, but it's inherited by the Environment from the Template:
        assertOutputEncodingEquals(// <- expected response.characterEncoding
        CFG_DEFAULT_ENCODING, // <- expected env.outputEncoding
        "UTF-8", // <- init-param
        initParamValue, FOO_OUT_UTF8_FTL);
        // Charset in content type is the strongest:
        assertOutputEncodingEquals(// <- expected response.characterEncoding
        "ISO-8859-2", // <- expected env.outputEncoding
        null, // <- init-param
        initParamValue, // ContentType init-param
        "text/html; charset=ISO-8859-2", FOO_FTL);
        assertOutputEncodingEquals(// <- expected response.characterEncoding
        "ISO-8859-2", // <- expected env.outputEncoding
        null, // <- init-param
        initParamValue, // ContentType init-param
        "text/html; charset=ISO-8859-2", FOO_SRC_UTF8_FTL);
        assertOutputEncodingEquals(// <- expected response.characterEncoding
        "UTF-8", // <- expected env.outputEncoding
        null, // <- init-param
        initParamValue, CONTENT_TYPE_ATTR_WITH_CHARSET_FTL);
        assertOutputEncodingEquals(// <- expected response.characterEncoding
        "UTF-8", // <- expected env.outputEncoding
        null, // <- init-param
        initParamValue, // ContentType init-param
        "text/html; charset=ISO-8859-2", CONTENT_TYPE_ATTR_WITH_CHARSET_FTL);
    }
    // Non-legacy mode always keeps env.outputEncoding in sync. with the Servlet response encoding:
    assertOutputEncodingEquals(// <- expected response.characterEncoding
    CFG_DEFAULT_ENCODING, // <- expected env.outputEncoding
    CFG_DEFAULT_ENCODING, // <- init-param
    FreemarkerServlet.INIT_PARAM_VALUE_FROM_TEMPLATE, FOO_FTL);
    // Non-legacy mode considers the template-specific outputEncoding:
    assertOutputEncodingEquals(// <- expected response.characterEncoding
    "UTF-8", // <- expected env.outputEncoding
    "UTF-8", // <- init-param
    FreemarkerServlet.INIT_PARAM_VALUE_FROM_TEMPLATE, FOO_OUT_UTF8_FTL);
    // Non-legacy mode uses the template source encoding as a fallback for outputEncoding:
    assertOutputEncodingEquals(// <- expected response.characterEncoding
    "UTF-8", // <- expected env.outputEncoding
    "UTF-8", // <- init-param
    FreemarkerServlet.INIT_PARAM_VALUE_FROM_TEMPLATE, FOO_SRC_UTF8_FTL);
    // Not allowed to specify the charset in the contentType init-param:
    try {
        assertOutputEncodingEquals(// <- expected response.characterEncoding
        null, // <- expected env.outputEncoding
        null, // <- init-param
        FreemarkerServlet.INIT_PARAM_VALUE_FROM_TEMPLATE, // ContentType init-param
        "text/html; charset=ISO-8859-2", FOO_FTL);
        fail();
    } catch (ServletException e) {
        assertThat(e.getCause().getCause().getMessage(), containsString(FreemarkerServlet.INIT_PARAM_VALUE_LEGACY));
    }
    // But the legacy content_type template attribute can still set the output charset:
    assertOutputEncodingEquals(// <- expected response.characterEncoding
    "UTF-8", // <- expected env.outputEncoding
    "UTF-8", // <- init-param
    FreemarkerServlet.INIT_PARAM_VALUE_FROM_TEMPLATE, CONTENT_TYPE_ATTR_WITH_CHARSET_FTL);
    // Do not set mode:
    assertOutputEncodingEquals(// <- expected response.characterEncoding
    SERVLET_RESPONSE_DEFAULT_CHARSET, // <- expected env.outputEncoding
    SERVLET_RESPONSE_DEFAULT_CHARSET, // <- init-param
    FreemarkerServlet.INIT_PARAM_VALUE_DO_NOT_SET, FOO_FTL);
    assertOutputEncodingEquals(// <- expected response.characterEncoding
    SERVLET_RESPONSE_DEFAULT_CHARSET, // <- expected env.outputEncoding
    SERVLET_RESPONSE_DEFAULT_CHARSET, // <- init-param
    FreemarkerServlet.INIT_PARAM_VALUE_DO_NOT_SET, FOO_SRC_UTF8_FTL);
    assertOutputEncodingEquals(// <- expected response.characterEncoding
    SERVLET_RESPONSE_DEFAULT_CHARSET, // <- expected env.outputEncoding
    SERVLET_RESPONSE_DEFAULT_CHARSET, // <- init-param
    FreemarkerServlet.INIT_PARAM_VALUE_DO_NOT_SET, FOO_OUT_UTF8_FTL);
    // Not allowed to specify the charset in the contentType init-param:
    try {
        assertOutputEncodingEquals(// <- expected response.characterEncoding
        SERVLET_RESPONSE_DEFAULT_CHARSET, // <- expected env.outputEncoding
        SERVLET_RESPONSE_DEFAULT_CHARSET, // <- init-param
        FreemarkerServlet.INIT_PARAM_VALUE_DO_NOT_SET, // ContentType init-param
        "text/html; charset=ISO-8859-2", FOO_FTL);
        fail();
    } catch (ServletException e) {
        assertThat(e.getCause().getCause().getMessage(), containsString(FreemarkerServlet.INIT_PARAM_VALUE_LEGACY));
    }
    // The legacy content_type template attribute can still specify an output charset, though it will be ignored:
    assertOutputEncodingEquals(// <- expected response.characterEncoding
    SERVLET_RESPONSE_DEFAULT_CHARSET, // <- expected env.outputEncoding
    SERVLET_RESPONSE_DEFAULT_CHARSET, // <- init-param
    FreemarkerServlet.INIT_PARAM_VALUE_DO_NOT_SET, CONTENT_TYPE_ATTR_WITH_CHARSET_FTL);
    // Forced mode:
    assertOutputEncodingEquals(// <- expected response.characterEncoding
    "UTF-16LE", // <- expected env.outputEncoding
    "UTF-16LE", // <- init-param
    FreemarkerServlet.INIT_PARAM_VALUE_FORCE_PREFIX + "UTF-16LE", FOO_FTL);
    assertOutputEncodingEquals(// <- expected response.characterEncoding
    "UTF-16LE", // <- expected env.outputEncoding
    "UTF-16LE", // <- init-param
    FreemarkerServlet.INIT_PARAM_VALUE_FORCE_PREFIX + "UTF-16LE", FOO_SRC_UTF8_FTL);
    assertOutputEncodingEquals(// <- expected response.characterEncoding
    "UTF-16LE", // <- expected env.outputEncoding
    "UTF-16LE", // <- init-param
    FreemarkerServlet.INIT_PARAM_VALUE_FORCE_PREFIX + "UTF-16LE", FOO_OUT_UTF8_FTL);
    try {
        assertOutputEncodingEquals(// <- expected response.characterEncoding
        null, // <- expected env.outputEncoding
        null, // <- init-param
        FreemarkerServlet.INIT_PARAM_VALUE_FORCE_PREFIX + "noSuchCharset", FOO_FTL);
        fail();
    } catch (ServletException e) {
        assertThat(e.getCause().getCause(), instanceOf(UnsupportedCharsetException.class));
    }
    // Not allowed to specify the charset in the contentType init-param:
    try {
        assertOutputEncodingEquals(// <- expected response.characterEncoding
        "UTF-16LE", // <- expected env.outputEncoding
        "UTF-16LE", // <- init-param
        FreemarkerServlet.INIT_PARAM_VALUE_FORCE_PREFIX + "UTF-16LE", // ContentType init-param
        "text/html; charset=ISO-8859-2", FOO_FTL);
        fail();
    } catch (ServletException e) {
        assertThat(e.getCause().getCause().getMessage(), containsString(FreemarkerServlet.INIT_PARAM_VALUE_LEGACY));
    }
    // The legacy content_type template attribute can still specify an output charset, though it will be overridden:
    assertOutputEncodingEquals(// <- expected response.characterEncoding
    "UTF-16LE", // <- expected env.outputEncoding
    "UTF-16LE", // <- init-param
    FreemarkerServlet.INIT_PARAM_VALUE_FORCE_PREFIX + "UTF-16LE", CONTENT_TYPE_ATTR_WITH_CHARSET_FTL);
}

@Test
public void testFindTemplatePathSettingAssignmentsStart() {
    assertEquals(0, InitParamParser.findTemplatePathSettingAssignmentsStart("?settings()"));
    assertEquals(1, InitParamParser.findTemplatePathSettingAssignmentsStart("x?settings()"));
    assertEquals(1, InitParamParser.findTemplatePathSettingAssignmentsStart("x?settings(x=1, y=2)"));
    assertEquals(2, InitParamParser.findTemplatePathSettingAssignmentsStart("x ? settings ( x=1, y=2 ) "));
    assertEquals(1, InitParamParser.findTemplatePathSettingAssignmentsStart("x?settings(x=f(), y=g())"));
    assertEquals(1, InitParamParser.findTemplatePathSettingAssignmentsStart("x?settings(x=\"(\", y='(')"));
    assertEquals(1, InitParamParser.findTemplatePathSettingAssignmentsStart("x?settings(x=\"(\\\"\", y='(\\'')"));
    assertEquals(-1, InitParamParser.findTemplatePathSettingAssignmentsStart(""));
    assertEquals(-1, InitParamParser.findTemplatePathSettingAssignmentsStart("settings"));
    assertEquals(-1, InitParamParser.findTemplatePathSettingAssignmentsStart("settings()"));
    assertEquals(-1, InitParamParser.findTemplatePathSettingAssignmentsStart("x?settings"));
    assertEquals(-1, InitParamParser.findTemplatePathSettingAssignmentsStart("foo?/settings(x=1)"));
    assertEquals(-1, InitParamParser.findTemplatePathSettingAssignmentsStart("x?settings()x=1)"));
    assertEquals(-1, InitParamParser.findTemplatePathSettingAssignmentsStart("x?settings((x=1)"));
    try {
        assertEquals(0, InitParamParser.findTemplatePathSettingAssignmentsStart("x?setting(x = 1)"));
        fail();
    } catch (Exception e) {
        assertThat(e.getMessage(), containsString("\"setting\""));
    }
}

@Test
public void testCreateTemplateLoader() throws IOException {
    Configuration cfg = new Configuration(Configuration.VERSION_2_3_22);
    {
        ClassTemplateLoader ctl = (ClassTemplateLoader) InitParamParser.createTemplateLoader("classpath:templates", cfg, this.getClass(), null);
        assertEquals("templates/", ctl.getBasePackagePath());
        assertNull(ctl.getURLConnectionUsesCaches());
    }
    {
        ClassTemplateLoader ctl = (ClassTemplateLoader) InitParamParser.createTemplateLoader("classpath:templates?settings(URLConnectionUsesCaches=false)", cfg, this.getClass(), null);
        assertEquals("templates/", ctl.getBasePackagePath());
        assertEquals(Boolean.FALSE, ctl.getURLConnectionUsesCaches());
    }
    {
        MultiTemplateLoader mtl = (MultiTemplateLoader) InitParamParser.createTemplateLoader("[" + "templates?settings(URLConnectionUsesCaches=false, attemptFileAccess=false), " + "foo/templates?settings(URLConnectionUsesCaches=true), " + "classpath:templates, " + "classpath:foo/templates?settings(URLConnectionUsesCaches=true)" + "]", cfg, this.getClass(), new MockServletContext());
        assertEquals(4, mtl.getTemplateLoaderCount());
        final WebappTemplateLoader tl1 = (WebappTemplateLoader) mtl.getTemplateLoader(0);
        assertEquals(Boolean.FALSE, tl1.getURLConnectionUsesCaches());
        assertFalse(tl1.getAttemptFileAccess());
        final WebappTemplateLoader tl2 = (WebappTemplateLoader) mtl.getTemplateLoader(1);
        assertEquals(Boolean.TRUE, tl2.getURLConnectionUsesCaches());
        assertTrue(tl2.getAttemptFileAccess());
        final ClassTemplateLoader tl3 = (ClassTemplateLoader) mtl.getTemplateLoader(2);
        assertNull(tl3.getURLConnectionUsesCaches());
        final ClassTemplateLoader tl4 = (ClassTemplateLoader) mtl.getTemplateLoader(3);
        assertEquals(Boolean.TRUE, tl4.getURLConnectionUsesCaches());
    }
}

@Test
public void testParseCommaSeparatedTemplateLoaderList() {
    assertEquals(Collections.emptyList(), InitParamParser.parseCommaSeparatedTemplatePaths(""));
    assertEquals(Collections.emptyList(), InitParamParser.parseCommaSeparatedTemplatePaths("  "));
    assertEquals(Collections.emptyList(), InitParamParser.parseCommaSeparatedTemplatePaths(","));
    assertEquals(ImmutableList.of("a"), InitParamParser.parseCommaSeparatedTemplatePaths("a"));
    assertEquals(ImmutableList.of("a"), InitParamParser.parseCommaSeparatedTemplatePaths("  a  "));
    assertEquals(ImmutableList.of("a", "b", "c"), InitParamParser.parseCommaSeparatedTemplatePaths("a,b,c"));
    assertEquals(ImmutableList.of("a", "b", "c"), InitParamParser.parseCommaSeparatedTemplatePaths("  a  ,  b  ,  c  "));
    assertEquals(ImmutableList.of("a", "b", "c"), InitParamParser.parseCommaSeparatedTemplatePaths("a,b,c,"));
    try {
        assertEquals(ImmutableList.of("a", "b", "c"), InitParamParser.parseCommaSeparatedTemplatePaths("a,b,,c"));
    } catch (Exception e) {
        assertThat(e.getMessage(), containsString("comma"));
    }
    try {
        assertEquals(ImmutableList.of("a", "b", "c"), InitParamParser.parseCommaSeparatedTemplatePaths(",a,b,c"));
    } catch (Exception e) {
        assertThat(e.getMessage(), containsString("comma"));
    }
    try {
        assertEquals(ImmutableList.of("a", "b", "c"), InitParamParser.parseCommaSeparatedTemplatePaths(",a,b,c"));
    } catch (Exception e) {
        assertThat(e.getMessage(), containsString("comma"));
    }
    assertEquals(ImmutableList.of("a?settings(1)", "b", "c?settings(2)"), InitParamParser.parseCommaSeparatedTemplatePaths("a?settings(1),b,c?settings(2)"));
    assertEquals(ImmutableList.of("a ? settings ( 1 )", "b", "c ? settings ( 2 )"), InitParamParser.parseCommaSeparatedTemplatePaths(" a ? settings ( 1 ) , b , c ? settings ( 2 ) "));
    assertEquals(ImmutableList.of("a?settings(1,2,3)", "b?settings(1,2)", "c?settings()"), InitParamParser.parseCommaSeparatedTemplatePaths("a?settings(1,2,3),b?settings(1,2),c?settings()"));
    assertEquals(ImmutableList.of("a?settings(x=1, y=2)"), InitParamParser.parseCommaSeparatedTemplatePaths("a?settings(x=1, y=2)"));
    try {
        InitParamParser.parseCommaSeparatedTemplatePaths("a?foo(x=1, y=2)");
    } catch (Exception e) {
        assertThat(e.getMessage(), containsString("settings"));
    }
}

